37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "title")
43	    private String title;
44	
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "address_line1")
50	    private String addressLine1;
51	
52	    @Column(name = "address_line2")
53	    private String addressLine2;
54	
55	    @Column(name = "city")
56	    @NotEmpty
57	    private String city;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    private String email;
66	
67	    @Column(name = "postcode")
68	    private String postcode;
69	
70	    @Column(name = "registration_date")
71	    private LocalDate registrationDate;
72	
73	    @Column(name = "birth_date")
74	    private LocalDate birthDate;
75	
76	    @Column(name = "customer_code")
77	    private String customerCode;
78	
79	    @Column(name = "household_id")
80	    private String householdId;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "membership_number")
89	    private String membershipNumber;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "deleted", nullable = false)
95	    private boolean deleted;
96	
97	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
98	    private Set<Pet> pets;
99	
100	    /**
101	     * Default the registration date to the server's current date when none was
102	     * supplied, then roll the effective date forward onto a business day so a
103	     * weekend registration date always lands on the following Monday. Runs only
104	     * on insert.
105	     */
106	    @PrePersist
107	    private void defaultRegistrationDate() {
108	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
109	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
110	    }
111	
112	    public String getTitle() {
113	        return this.title;
114	    }
115	
116	    public void setTitle(String title) {
117	        this.title = title;
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    public void setEmail(String email) {
165	        this.email = email;
166	    }
167	
168	    public String getPostcode() {
169	        return this.postcode;
170	    }
171	
172	    public void setPostcode(String postcode) {
173	        this.postcode = postcode;
174	    }
175	
176	    public LocalDate getRegistrationDate() {
177	        return this.registrationDate;
178	    }
179	
180	    public void setRegistrationDate(LocalDate registrationDate) {
181	        this.registrationDate = registrationDate;
182	    }
183	
184	    public LocalDate getBirthDate() {
185	        return this.birthDate;
186	    }
