189	        this.birthDate = birthDate;
190	    }
191	
192	    public String getCustomerCode() {
193	        return this.customerCode;
194	    }
195	
196	    public void setCustomerCode(String customerCode) {
197	        this.customerCode = customerCode;
198	    }
199	
200	    public String getHouseholdId() {
201	        return this.householdId;
202	    }
203	
204	    public void setHouseholdId(String householdId) {
205	        this.householdId = householdId;
206	    }
207	
208	    public Integer getNamesakeCount() {
209	        return this.namesakeCount;
210	    }
211	
212	    public void setNamesakeCount(Integer namesakeCount) {
213	        this.namesakeCount = namesakeCount;
214	    }
