232	    public Integer getPossibleDuplicateOf() {
233	        return this.possibleDuplicateOf;
234	    }
235	
236	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
237	        this.possibleDuplicateOf = possibleDuplicateOf;
238	    }
239	
240	    /**
241	     * Return whether this owner has been soft-deleted. A newly created owner is not deleted; a
242	     * {@code DELETE /api/owners/{id}} flags the owner deleted while retaining its record.
243	     */
244	    public boolean isDeleted() {
245	        return this.deleted;
246	    }
247	
248	    public void setDeleted(boolean deleted) {
249	        this.deleted = deleted;
250	    }
251	
252	    /**
253	     * Return whether this owner is a possible duplicate: true when it was created while an existing
254	     * owner already shared its last name and postcode under a different telephone, i.e. when a
255	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
256	     */
257	    @Transient
258	    public boolean getPossibleDuplicate() {
259	        return this.possibleDuplicateOf != null;
260	    }
261	
262	    /**
263	     * Return this owner's name formatted as {@code LastName, FirstName}.
264	     */
265	    @Transient
266	    public String getDisplayName() {
267	        return this.getLastName() + ", " + this.getFirstName();
268	    }
269	
270	    /**
271	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
272	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
273	     */
274	    @Transient
275	    public String getSalutation() {
276	        if (this.title == null || this.title.isBlank()) {
277	            return this.getLastName();
278	        }
279	        return this.title + " " + this.getLastName();
280	    }
281	
282	    /**
283	     * Return this owner's telephone formatted for human display: the country code, a space, then
284	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
285	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
286	     */
287	    @Transient
288	    public String getTelephoneDisplay() {
289	        return TelephoneFormatter.format(this.telephone);
290	    }
291	
292	    /**
293	     * Return this owner's identity key: the derived value formed as
294	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
295	     * contributes an empty segment). Members of the same household share a household id but, having
296	     * different telephones, still have distinct identity keys. The telephone and email are expected
297	     * to already be in their normalized storage form.
298	     */
299	    @Transient
300	    public String getIdentityKey() {
301	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
302	    }
303	
304	    private static String orEmpty(String value) {
305	        return value == null ? "" : value;
306	    }
307	
308	    /**
309	     * Return this owner's locality: the REGION segment of the owner's
310	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
311	     * When no customer code has been assigned yet the region is resolved directly from the
312	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
313	     */
314	    @Transient
315	    public String getLocality() {
316	        if (this.customerCode != null && !this.customerCode.isBlank()) {
317	            return CustomerCodeGenerator.regionOf(this.customerCode);
318	        }
319	        return RegionResolver.regionFor(this.postcode, this.city);
320	    }
321	
322	    /**
323	     * Return this owner's timezone: the IANA name mapped from the owner's
324	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
325	     * region has no known timezone.
326	     */
327	    @Transient
328	    public String getTimezone() {
329	        return RegionTimezones.timezoneOf(getLocality());
330	    }
331	
332	    /**
333	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
334	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
335	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
336	     * for long tenure ({@link #getTenureDays() tenure} of more than 365 days).
337	     */
338	    @Transient
339	    public int getMembershipPoints() {
340	        boolean hasEmail = this.email != null && !this.email.isEmpty();
341	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
342	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
343	        boolean longTenure = getTenureDays() > 365;
344	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
345	    }
346	
347	    /**
348	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
349	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
350	     */
351	    @Transient
352	    public int getMembershipLevel() {
353	        return MembershipPoints.levelFor(getMembershipPoints());
354	    }
355	
356	    /**
357	     * Return this owner's tenure in whole days: the number of days elapsed from the
358	     * {@link #getRegistrationDate() registration date} to today. A newly created owner
359	     * whose registration date is today has zero tenure. Zero when no registration date
360	     * is known.
361	     */
362	    @Transient
363	    public long getTenureDays() {
364	        if (this.registrationDate == null) {
365	            return 0;
366	        }
367	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
368	    }
369	
370	    /**
371	     * Return this owner's check digit: the single Luhn check digit computed over the
372	     * digits of the {@link #getCustomerCode() customer code}.
373	     */
374	    @Transient
375	    public int getCheckDigit() {
376	        return LuhnCheckDigit.of(this.customerCode);
377	    }
378	
379	    /**
380	     * Return this owner's preferred contact channel: {@code EMAIL} when an
381	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
382	     */
383	    @Transient
384	    public String getContactPreference() {
385	        boolean hasEmail = this.email != null && !this.email.isEmpty();
386	        return hasEmail ? "EMAIL" : "PHONE";
387	    }
388	
389	    /**
390	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
391	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
392	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
393	     */
394	    @Transient
395	    public String getAgeBand() {
396	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
397	        return ageBand == null ? null : ageBand.name();
398	    }
399	
400	    protected Set<Pet> getPetsInternal() {
401	        if (this.pets == null) {
402	            this.pets = new HashSet<>();
403	        }
404	        return this.pets;
405	    }
406	
407	    protected void setPetsInternal(Set<Pet> pets) {
408	        this.pets = pets;
409	    }
410	
411	    public List<Pet> getPets() {
412	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
413	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
414	        return Collections.unmodifiableList(sortedPets);
415	    }
416	
417	    public void setPets(List<Pet> pets) {
418	        this.pets = new HashSet<>(pets);
419	    }
420	
421	    public void addPet(Pet pet) {
422	        getPetsInternal().add(pet);
423	        pet.setOwner(this);
424	    }
425	
426	    /**
427	     * Return the Pet with the given name, or null if none found for this Owner.
428	     *
429	     * @param name to test
430	     * @return true if pet name is already in use
431	     */
432	    public Pet getPet(String name) {
433	        return getPet(name, false);
434	    }
435	
436	    /**
437	     * Return the Pet with the given name, or null if none found for this Owner.
438	     *
439	     * @param name to test
440	     * @return true if pet name is already in use
441	     */
442	    public Pet getPet(String name, boolean ignoreNew) {
443	        name = name.toLowerCase();
444	        for (Pet pet : getPetsInternal()) {
445	            if (!ignoreNew || !pet.isNew()) {
446	                String compName = pet.getName();
447	                compName = compName.toLowerCase();
448	                if (compName.equals(name)) {
449	                    return pet;
450	                }
451	            }
452	        }
453	        return null;
454	    }
455	
456	    public Pet getPet(Integer petId) {
457	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
458	    }
459	
460	    @Override
461	    public String toString() {
462	        return new ToStringCreator(this)
463	
464	            .append("id", this.getId())
465	            .append("new", this.isNew())
466	            .append("lastName", this.getLastName())
467	            .append("firstName", this.getFirstName())
468	            .append("address", this.address)
469	            .append("city", this.city)
470	            .append("telephone", this.telephone)
471	            .append("email", this.email)
472	            .toString();
473	    }
474	}
